<template><view v-if="work" class="home-book-cover"><button @click="$emit('open',work.id)"><image v-if="url" :src="url" mode="aspectFit"/><view><text class="book-cover-title">{{work.snapshot?.renderPayload?.title||'属于它的一页'}}</text><text class="book-cover-caption">{{url?'翻开已收藏的作品':'作品封面尚未就绪 · 点此查看'}}</text></view><uni-icons type="right" size="18" color="currentColor"/></button></view><NarrativeCanvas ref="canvas"/></template>
<script>
import NarrativeCanvas from './NarrativeCanvas.vue';
import {getNarrativeStore} from '../common/narrative-store.js';
import {captureDataScope,isDataScopeCurrent} from '../common/scoped-storage.js';
export default{components:{NarrativeCanvas},props:{pet:Object},emits:['open','availability'],data(){return{work:null,url:'',epoch:0};},mounted(){this.load();},beforeUnmount(){this.epoch++;},watch:{'pet.id'(){this.load();},'pet.relationshipStage'(){this.load();}},methods:{async load(){this.url='';this.work=null;const scope=captureDataScope(),epoch=++this.epoch,pet=this.pet;if(!scope.ready||!pet?.id)return;const valid=()=>isDataScopeCurrent(scope)&&epoch===this.epoch&&this.pet?.id===pet.id;try{const works=Object.values(getNarrativeStore(pet.id,scope).read().works).filter(w=>w.snapshot?.renderPayload&&w.snapshot.renderPayload.mode===(pet.relationshipStage==='deceased'?'deceased':'current')).sort((a,b)=>b.createdAt-a.createdAt);this.work=works[0]||null;this.$emit('availability',Boolean(this.work));if(!this.work)return;await this.$nextTick();const [url]=await this.$refs.canvas.render(this.work.snapshot.renderPayload,scope,pet.id,valid,{firstPageOnly:true});if(valid())this.url=url;}catch(_){/* Keep an honest link; do not replace an owned cover with an example. */}}}};
</script>
<style scoped>.home-book-cover{margin-top:var(--ui-s5)}.home-book-cover button{display:flex;align-items:center;gap:var(--ui-s4);padding:var(--ui-s4);border-radius:var(--ui-r-group);background:var(--ui-surface);color:var(--ui-ink);text-align:left;line-height:24px}.home-book-cover button:after{border:0}.home-book-cover image{width:76px;height:101px;border-radius:var(--ui-r-thumb);flex-shrink:0}.home-book-cover button>view{flex:1;min-width:0}.book-cover-title,.book-cover-caption{display:block}.book-cover-title{font-size:var(--ui-body)}.book-cover-caption{font-size:var(--ui-small);color:var(--ui-muted);margin-top:var(--ui-s2)}</style>
